30	/// Export a frame into an SVG file.
31	#[typst_macros::time(name = "svg")]
32	pub fn svg(page: &Page, opts: &SvgOptions) -> String {
33	    let (size, ts) = page_bleed(page, opts);
34	
35	    let mut renderer = SVGRenderer::new();
36	    let mut xml = XmlWriter::new(xml_options(opts.pretty));
37	    let mut svg = svg_header(&mut xml, size);
38	
39	    let state = State::new(size);
40	    renderer.render_page(&mut svg, &state, ts, page);
41	    renderer.finalize(svg);
42	    xml.end_document()
43	}
44	
45	/// Export a page into an SVG file as part of a bundle.
46	///
47	/// Takes additional `anchor` locations that will be serialized as linkable
48	/// points. This enables other documents in the bundle to link into the
49	/// resulting SVG. Also takes a `link_resolver` for resolving cross-document
50	/// links.
51	#[typst_macros::time(name = "svg in bundle")]
52	pub fn svg_in_bundle(
53	    page: &Page,
54	    opts: &SvgOptions,
55	    anchors: &[(Point, EcoString)],
56	    link_resolver: Tracked<LateLinkResolver>,
57	) -> String {
58	    let (size, ts) = page_bleed(page, opts);
59	
60	    let mut renderer = SVGRenderer::with_options(Some(link_resolver));
61	    let mut xml = XmlWriter::new(xml_options(opts.pretty));
62	    let mut svg = svg_header(&mut xml, size);
63	
64	    let state = State::new(size);
65	    renderer.render_page(&mut svg, &state, ts, page);
66	
67	    for (pos, id) in anchors {
68	        renderer.render_anchor(&mut svg, *pos, id);
69	    }
70	
71	    renderer.finalize(svg);
72	    xml.end_document()
73	}
74	
75	/// Export a frame into an SVG suitable for embedding into HTML.
76	///
77	/// Takes additional `anchor` locations that will be serialized as linkable
78	/// points. This enables other documents in the bundle to link into the
79	/// resulting SVG. Also takes a `link_resolver` for resolving links between the
80	/// frame and remaining document.
81	#[typst_macros::time(name = "svg in html")]
82	pub fn svg_in_html(
83	    frame: &Frame,
84	    text_size: Abs,
85	    pretty: bool,
86	    id: Option<&str>,
87	    styles: &str,
88	    anchors: &[(Point, EcoString)],
89	    link_resolver: Tracked<LateLinkResolver>,
90	) -> String {
91	    let mut renderer = SVGRenderer::with_options(Some(link_resolver));
92	    let mut xml = XmlWriter::new(xml_options(pretty));
93	    let mut svg = svg_header_with_custom_attrs(&mut xml, frame.size(), |svg| {
94	        if let Some(id) = id {
95	            svg.attr("id", id);
96	        }
97	        svg.attr_with("style", |attr| {
98	            // TODO: Maybe make this a little more elegant?
99	            attr.push_str("overflow: visible; width: ");
100	            attr.push_num(frame.width() / text_size);
101	            attr.push_str("em; height: ");
102	            attr.push_num(frame.height() / text_size);
103	            attr.push_str("em;");
104	            if !styles.is_empty() {
105	                attr.push_str(" ");
106	                attr.push_str(styles);
107	            }
108	        });
109	    });
110	
111	    let state = State::new(frame.size());
112	    renderer.render_frame(&mut svg, &state, frame);
113	
114	    for (pos, id) in anchors {
115	        renderer.render_anchor(&mut svg, *pos, id);
116	    }
117	
118	    renderer.finalize(svg);
119	    xml.end_document()
120	}
121	
122	/// Export a document with potentially multiple pages into a single SVG file.
123	///
124	/// The gap will be added between the individual pages.
125	pub fn svg_merged(document: &PagedDocument, opts: &SvgOptions, gap: Abs) -> String {
126	    let num_gaps = document.pages().len().saturating_sub(1) as f64;
127	    let mut size = Size::new(Abs::zero(), num_gaps * gap);
128	    for page in document.pages() {
129	        let (page_size, _ts) = page_bleed(page, opts);
130	        size.x.set_max(page_size.x);
131	        size.y += page_size.y;
132	    }
133	
134	    let mut renderer = SVGRenderer::new();
135	    let mut xml = XmlWriter::new(xml_options(opts.pretty));
136	    let mut svg = svg_header(&mut xml, size);
137	
138	    let mut y = Abs::zero();
139	    for page in document.pages() {
140	        let (page_size, bleed_ts) = page_bleed(page, opts);
141	        let state = State::new(page_size);
142	        renderer.render_page(
143	            &mut svg,
144	            &state,
145	            Transform::translate(Abs::zero(), y).pre_concat(bleed_ts),
146	            page,
147	        );
148	        y += page_size.y + gap;
149	    }
150	
151	    renderer.finalize(svg);
152	    xml.end_document()
153	}
154	
155	fn page_bleed(page: &Page, opts: &SvgOptions) -> (Size, Transform) {
156	    let bleed = if opts.render_bleed { page.bleed } else { Sides::default() };
157	    let size = page.frame.size() + bleed.sum_by_axis();
158	    let ts = Transform::translate(bleed.left, bleed.top);
159	    (size, ts)
160	}
161	
162	fn xml_options(pretty: bool) -> xmlwriter::Options {
163	    xmlwriter::Options {
164	        use_single_quote: false,
165	        indent: if pretty {
166	            xmlwriter::Indent::Spaces(2)
167	        } else {
168	            xmlwriter::Indent::None
169	        },
170	        attributes_indent: xmlwriter::Indent::None,
171	    }
172	}
173	
174	/// Settings for SVG export.
175	#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
176	pub struct SvgOptions {
177	    /// By default, SVG documents are bounded to the page size. In some
178	    /// circumstances, such as when preparing documents for print, it may be
179	    /// desirable to include content beyond these bounds to account for bleed
180	    /// margins. This field allows expanding the document area to include such
181	    /// bleed.
182	    pub render_bleed: bool,
183	    /// Whether to format the SVG in a human-readable way.
184	    pub pretty: bool,
185	}
186	
187	/// Renders one or multiple frames to an SVG file.
188	struct SVGRenderer<'a> {
189	    /// The document's introspector, if we're writing an HTML frame.
190	    link_resolver: Option<Tracked<'a, LateLinkResolver<'a>>>,
191	    /// Prepared glyphs.
192	    glyphs: Deduplicator<Option<RenderedGlyph>>,
193	    /// Clip paths are used to clip a group. A clip path is a path that defines
194	    /// the clipping region. The clip path is referenced by the `clip-path`
195	    /// attribute of the group. The clip path is in the format of `M x y L x y C
196	    /// x1 y1 x2 y2 x y Z`.
197	    clip_paths: Deduplicator<EcoString>,
198	    /// These are the actual gradients being written in the SVG file.
199	    /// These gradients are deduplicated because they do not contain the transform
200	    /// matrix, allowing them to be reused across multiple invocations.
201	    ///
202	    /// The `Ratio` is the aspect ratio of the gradient, this is used to correct
203	    /// the angle of the gradient.
204	    gradients: Deduplicator<(Gradient, Ratio)>,
205	    /// Deduplicated gradients with transform matrices. They use a reference
206	    /// (`href`) to a "source" gradient instead of being defined inline.
207	    /// This saves a lot of space since gradients are often reused but with
208	    /// different transforms. Therefore this allows us to reuse the same gradient
209	    /// multiple times.
210	    gradient_refs: Deduplicator<GradientRef>,
211	    /// These are the gradients that compose a conic gradient.
212	    conic_subgradients: Deduplicator<SVGSubGradient>,
213	    /// These are the actual tilings being written in the SVG file.
214	    /// These tilings are deduplicated because they do not contain the transform
215	    /// matrix, allowing them to be reused across multiple invocations.
216	    ///
217	    /// The `String` is the rendered tiling frame.
218	    tilings: Deduplicator<Tiling>,
219	    /// Deduplicated tilings with transform matrices. They use a reference
220	    /// (`href`) to a "source" tiling instead of being defined inline.
221	    /// This saves a lot of space since tilings are often reused but with
222	    /// different transforms. Therefore this allows us to reuse the same gradient
223	    /// multiple times.
224	    tiling_refs: Deduplicator<TilingRef>,
225	}
226	
227	/// Contextual information for rendering.
228	#[derive(Copy, Clone)]
229	struct State {
230	    /// The transform of the current item.
231	    transform: Transform,
232	    /// The size of the first hard frame in the hierarchy.
233	    size: Size,
234	}
235	
236	impl State {
237	    fn new(size: Size) -> Self {
238	        Self { size, transform: Transform::identity() }
239	    }
240	
241	    /// Pre translate the current item's transform.
242	    fn pre_translate(self, pos: Point) -> Self {
243	        self.pre_concat(Transform::translate(pos.x, pos.y))
244	    }
245	
246	    /// Pre concat the current item's transform.
247	    fn pre_concat(self, transform: Transform) -> Self {
248	        Self {
249	            transform: self.transform.pre_concat(transform),
250	            ..self
251	        }
252	    }
253	
254	    /// Sets the size of the first hard frame in the hierarchy.
255	    fn with_size(self, size: Size) -> Self {
256	        Self { size, ..self }
257	    }
258	
259	    /// Sets the current item's transform.
260	    fn with_transform(self, transform: Transform) -> Self {
261	        Self { transform, ..self }
262	    }
263	}
264	
265	impl<'a> SVGRenderer<'a> {
266	    /// Create a new SVG renderer with empty glyph and clip path.
267	    fn new() -> Self {
268	        Self::with_options(None)
269	    }
270	
271	    /// Create a new SVG renderer with the given configuration.
272	    fn with_options(link_resolver: Option<Tracked<'a, LateLinkResolver<'a>>>) -> Self {
273	        SVGRenderer {
274	            link_resolver,
275	            glyphs: Deduplicator::new('g'),
276	            clip_paths: Deduplicator::new('c'),
277	            gradients: Deduplicator::new('f'),
278	            gradient_refs: Deduplicator::new('r'),
279	            conic_subgradients: Deduplicator::new('s'),
280	            tilings: Deduplicator::new('t'),
281	            tiling_refs: Deduplicator::new('p'),
282	        }
283	    }
284	
285	    /// Render a page with the given transform.
286	    fn render_page(
287	        &mut self,
288	        svg: &mut SvgElem,
289	        state: &State,
290	        ts: Transform,
291	        page: &Page,
292	    ) {
293	        let mut svg = svg.lazy_elem("g");
294	        if !ts.is_identity() {
295	            svg.init().attr("transform", SvgTransform(ts));
296	        }
297	
298	        if let Some(fill) = page.fill_or_white() {
299	            let shape =
300	                Geometry::Rect(page.frame.size() + page.bleed.sum_by_axis()).filled(fill);
301	            let state =
302	                &state.pre_translate(Point { x: -page.bleed.left, y: -page.bleed.top });
303	            self.render_shape(svg.lazy(), state, &shape);
304	        }
305	
306	        self.render_frame(svg.lazy(), state, &page.frame);
307	    }
308	
309	    /// Render a frame with the given transform.
310	    fn render_frame(&mut self, svg: &mut SvgElem, state: &State, frame: &Frame) {
311	        for (pos, item) in frame.items() {
312	            let state = state.pre_translate(*pos);
313	            match item {
314	                FrameItem::Group(group) => self.render_group(svg, &state, group),
315	                FrameItem::Text(text) => self.render_text(svg, &state, text),
316	                FrameItem::Shape(shape, _) => self.render_shape(svg, &state, shape),
317	                FrameItem::Image(image, size, _) => {
318	                    self.render_image(svg, &state, image, size);
319	                }
320	                FrameItem::Link(dest, size) => self.render_link(svg, &state, dest, *size),
321	                FrameItem::Tag(_) => {}
322	            }
323	        }
324	    }
325	
326	    /// Render a group. If the group has `clips` set to true, a clip path will
327	    /// be created.
328	    fn render_group(&mut self, svg: &mut SvgElem, state: &State, group: &GroupItem) {
329	        let mut svg = svg.lazy_elem("g");
330	
331	        let state = match group.frame.kind() {
332	            FrameKind::Soft => state.pre_concat(group.transform),
333	            FrameKind::Hard => {
334	                // Always generate a group for hard frames.
335	                svg.init();
336	
337	                let transform = state.transform.pre_concat(group.transform);
338	                if !transform.is_identity() {
339	                    svg.init().attr("transform", SvgTransform(transform));
340	                }
341	                state
342	                    .with_transform(Transform::identity())
343	                    .with_size(group.frame.size())
344	            }
345	        };
346	
347	        if let Some(label) = group.label {
348	            svg.init().attr("data-typst-label", label.resolve());
349	        }
350	
351	        if let Some(clip_curve) = &group.clip {
352	            let offset = Point::new(state.transform.tx, state.transform.ty);
353	            let id = self.clip_paths.insert_with((clip_curve, offset), || {
354	                shape::convert_curve(offset, clip_curve)
355	            });
356	            svg.init().attr("clip-path", SvgUrl(id));
357	        }
358	
359	        self.render_frame(svg.lazy(), &state, &group.frame);
360	    }
361	
362	    /// Render a link element.
363	    fn render_link(
364	        &mut self,
365	        svg: &mut SvgElem,
366	        state: &State,
367	        dest: &Destination,
368	        size: Size,
369	    ) {
370	        let mut a = svg.elem("a");
371	        if !state.transform.is_identity() {
372	            a.attr("transform", SvgTransform(state.transform));
373	        }
374	
375	        match dest {
376	            Destination::Url(url) => {
377	                a.attr("href", url.as_str());
378	                a.attr("xlink:href", url.as_str());
379	            }
380	            Destination::Position(_) => {
381	                // TODO: Links on the same page could be supported.
382	            }
383	            Destination::Location(loc) => {
384	                // TODO: Location links on the same page could also be supported
385	                // outside of HTML.
386	                if let Some(resolver) = self.link_resolver
387	                    && let Some(link) = resolver.resolve(*loc)
388	                    && let Ok(uri) = link.into_relative_uri()
389	                {
390	                    a.attr("href", &uri);
391	                    a.attr("xlink:href", &uri);
392	                }
393	            }
394	        }
395	
396	        a.elem("rect")
397	            .attr("width", size.x.to_pt())
398	            .attr("height", size.y.to_pt())
399	            .attr("fill", "transparent")
400	            .attr("stroke", "none");
401	    }
402	
403	    /// Renders a linkable point that can be used to link into an HTML frame.
404	    fn render_anchor(&mut self, svg: &mut SvgElem, pos: Point, id: &str) {
405	        svg.elem("g")
406	            .attr("id", id)
407	            .attr("transform", SvgTransform(Transform::translate(pos.x, pos.y)));
408	    }
409	
410	    /// Finalize the SVG file. This must be called after all rendering is done.
411	    fn finalize(mut self, mut svg: SvgElem) {
412	        self.write_glyph_defs(&mut svg);
413	        self.write_clip_path_defs(&mut svg);
414	        self.write_gradients(&mut svg);
415	        self.write_gradient_refs(&mut svg);
416	        self.write_subgradients(&mut svg);
417	        self.write_tilings(&mut svg);
418	        self.write_tiling_refs(&mut svg);
419	    }
420	
421	    /// Build the clip path definitions.
422	    fn write_clip_path_defs(&self, svg: &mut SvgElem) {
423	        if self.clip_paths.is_empty() {
424	            return;
425	        }
426	
427	        let mut defs = svg.elem("defs");
428	        for (id, path) in self.clip_paths.iter() {
429	            defs.elem("clipPath").attr("id", id).with(|svg| {
430	                svg.elem("path").attr("d", path);
431	            });
432	        }
433	    }
434	}
435	
436	/// Write the default SVG header, including a `typst-doc` class, the
437	/// `viewBox` and `width` and `height` attributes.
438	fn svg_header(xml: &mut XmlWriter, size: Size) -> SvgElem<'_> {
439	    svg_header_with_custom_attrs(xml, size, |_| {})
440	}
441	
442	/// Write the SVG header with additional attributes and standard attributes.
443	fn svg_header_with_custom_attrs(
444	    xml: &mut XmlWriter,
445	    size: Size,
446	    write_custom_attrs: impl FnOnce(&mut SvgElem),
447	) -> SvgElem<'_> {
448	    // Clamp the size of SVGs to at least one pt. resvg and probably also
449	    // other SVG parsers don't handle SVGs with 0 sized dimensions.
450	    let size = size.max(Size::splat(Abs::pt(1.0)));
451	
452	    let mut svg = SvgElem::new(xml, "svg");
453	
454	    write_custom_attrs(&mut svg);
455	
456	    svg.attr_with("viewBox", |attr| {
457	        attr.push_nums([0.0, 0.0, size.x.to_pt(), size.y.to_pt()]);
458	    });
459	    svg.attr_with("width", |attr| {
460	        attr.push_num(size.x.to_pt());
461	        attr.push_str("pt");
462	    });
463	    svg.attr_with("height", |attr| {
464	        attr.push_num(size.y.to_pt());
465	        attr.push_str("pt");
466	    });
467	    svg.attr("xmlns", "http://www.w3.org/2000/svg");
468	    svg.attr("xmlns:xlink", "http://www.w3.org/1999/xlink");
469	    svg.attr("xmlns:h5", "http://www.w3.org/1999/xhtml");
470	
471	    svg
472	}
473	
474	/// Deduplicates its elements. It is used to deduplicate glyphs and clip paths.
475	/// The `H` is the hash type, and `T` is the value type. The `PREFIX` is the
476	/// prefix of the index. This is used to distinguish between glyphs and clip
477	/// paths.
478	#[derive(Debug, Default, Clone)]
479	struct Deduplicator<T> {
480	    kind: char,
481	    map: IndexMap<u128, T, FxBuildHasher>,
482	}
483	
484	impl<T> Deduplicator<T> {
485	    fn new(kind: char) -> Self {
486	        Self { kind, map: IndexMap::default() }
487	    }
488	
489	    /// Inserts a value into the vector. If the hash is already present, returns
490	    /// the index of the existing value and `f` will not be called. Otherwise,
491	    /// inserts the value and returns the id of the inserted value.
492	    #[must_use = "returns the id of the inserted value"]
493	    fn insert_with<K, F>(&mut self, key: K, f: F) -> DedupId
494	    where
495	        K: Hash,
496	        F: FnOnce() -> T,
497	    {
498	        self.insert_with_val(key, f).0
499	    }
500	
501	    /// Same as [`Self::insert_with`], but it also returns a reference to the
502	    /// cached or inserted value.
503	    #[must_use]
504	    fn insert_with_val<K, F>(&mut self, key: K, f: F) -> (DedupId, &mut T)
505	    where
506	        K: Hash,
507	        F: FnOnce() -> T,
508	    {
509	        let hash = typst_utils::hash128(&key);
510	        let val = self.map.entry(hash).or_insert_with(f);
511	        (DedupId(self.kind, hash), val)
512	    }
513	
514	    /// Iterate over the elements alongside their ids.
515	    fn iter(&self) -> impl Iterator<Item = (DedupId, &T)> {
516	        self.map.iter().map(|(hash, v)| (DedupId(self.kind, *hash), v))
517	    }
518	
519	    /// Returns true if the deduplicator is empty.
520	    fn is_empty(&self) -> bool {
521	        self.map.is_empty()
522	    }
523	}
524	
525	/// Identifies a `<def>`.
526	#[derive(Debug, Copy, Clone, Eq, PartialEq, Ord, PartialOrd, Hash)]
527	struct DedupId(char, u128);
528	
529	impl SvgDisplay for DedupId {
530	    fn fmt(&self, f: &mut impl SvgWrite) {
531	        let Self(kind, hash) = *self;
532	        f.push_char(kind);
533	
534	        let mut digits = [0; 32];
535	        for (i, byte) in hash.to_be_bytes().into_iter().enumerate() {
536	            digits[2 * i] = to_hex_digit((byte >> 4) & 0x0F);
537	            digits[2 * i + 1] = to_hex_digit(byte & 0x0F);
538	        }
539	
540	        // The digits are all valid ASCII hex characters.
541	        let str = std::str::from_utf8(&digits).unwrap();
542	        f.push_str(str.trim_start_matches('0'));
543	
544	        fn to_hex_digit(nibble: u8) -> u8 {
545	            match nibble {
546	                0..10 => b'0' + nibble,
547	                _ => b'A' + (nibble - 10),
548	            }
549	        }
550	    }
551	}
